import type { Translate } from "./i18n";
import type { CaseFile } from "./types";
import historicalDemo from "./historicalDemo.json";

/** Frozen synthetic evidence, generated by scripts/build_historical_demo.py.
 * This local view never submits a case, approval or execution to the API.
 * Its plan, readiness and relationships retain their original hash binding.
 */
export function buildFixtureCase(_t: Translate): CaseFile {
  // The generator validates the closed, bound evidence projection before publication.
  return structuredClone(historicalDemo.case) as unknown as CaseFile;
}
